// This code checks for hypocrisy in a given statement
function isHypocritical(statement) {
    // Define keywords that might indicate hypocrisy
    const keywords = [say, do, preach, practice, contradict];

    // Check if the statement contains any of the keywords
    for (let keyword of keywords) {
        if (statement.includes(keyword)) {
            return true;
        }
    }
    return false;
}

// Example usage
const comment = Hypocrisy;
console.log(isHypocritical(comment)); // Output: false
```

