// This code snippet is a qualitative representation of the concept PublicShame.
// It is intended to illustrate the social dynamics and emotional impact associated with public shaming.

class PublicShame {
    private String target;
    private String platform;
    private String reason;
    private List<String> observers;
    private boolean isResolved;

    public PublicShame(String target, String platform, String reason) {
        this.target = target;
        this.platform = platform;
        this.reason = reason;
        this.observers = new ArrayList<>();
        this.isResolved = false;
    }

    public void addObserver(String observer) {
        observers.add(observer);
    }

    public void resolve() {
        isResolved = true;
        notifyObservers();
    }

    private void notifyObservers() {
        for (String observer : observers) {
            System.out.println(Notification to  + observer + : The public shaming of  + target +  has been resolved.);
        }
    }

    @Override
    public String toString() {
        return PublicShame{ +
                target=' + target + '\'' +
                , platform=' + platform + '\'' +
                , reason=' + reason + '\'' +
                , observers= + observers +
                , isResolved= + isResolved +
                '}';
    }
}
