// The character will exhibit a fear reaction when encountering a specific trigger.

class Character {
    constructor(name) {
        this.name = name;
        this.isAfraid = false;
    }

    encounter(trigger) {
        if (trigger === 'scaryMonster') {
            this.fearResponse();
        }
    }

    fearResponse() {
        this.isAfraid = true;
        console.log(`${this.name} is afraid!`);
        // Additional fear behavior can be implemented here
    }
}

const hero = new Character('Hero');
hero.encounter('scaryMonster'); // Output: Hero is afraid!
