// The code below demonstrates a simple function to calculate the factorial of a number.
// This is a qualitative example to illustrate the concept of recursion.

function factorial(n) {
    if (n === 0) {
        return 1;
    }
    return n * factorial(n - 1);
}

// Usage example
console.log(factorial(5)); // Output: 120
